package dev.vessel.kernel.sanitizer;

/**
 * Immutable audit report generated by {@link DirectBufferLeakWatchdog}.
 *
 * <p>Strictly adheres to Rule 17 with zero inner, nested, or anonymous classes.</p>
 *
 * @param activeTrackedBuffers count of direct byte buffers currently registered under watchdog monitoring
 * @param orphanedBuffersFreed count of leaked direct buffers explicitly deallocated
 * @param reclaimedBytes total off-heap bytes successfully reclaimed
 * @param currentDirectAllocatedBytes snapshot of estimated direct memory actively held
 * @param durationNanos execution time of the audit pass in nanoseconds
 *
 * @version 1.0.0
 * @author VESSEL Engine Team
 */
public record DirectBufferAuditReport(
        int activeTrackedBuffers,
        int orphanedBuffersFreed,
        long reclaimedBytes,
        long currentDirectAllocatedBytes,
        long durationNanos
) {
    public boolean hasReclaimedMemory() {
        return orphanedBuffersFreed > 0 && reclaimedBytes > 0;
    }
}
